struct FChatMessage
{
	FString SenderName;
	FString SenderSteamName;
	FString SenderTribeName;
	unsigned int SenderId;
	FString Message;
	FString Receiver;
	int SenderTeamIndex;
	long double ReceivedTime;
	TEnumAsByte<EChatSendMode::Type> SendMode;
	unsigned int RadioFrequency;
	TEnumAsByte<enum EChatType::Type> ChatType;
	UTexture2D* SenderIcon;
	FString UserId;

	FChatMessage()
		: SenderName(""),
		SenderSteamName(""),
		SenderTribeName(""),
		SenderId(0),
		Message(""),
		Receiver(""),
		SenderTeamIndex(0),
		ReceivedTime(-1),
		SendMode(EChatSendMode::GlobalChat),
		RadioFrequency(0),
		ChatType(EChatType::GlobalChat),
		SenderIcon(nullptr),
		UserId("")
	{
	}

	FChatMessage(FChatMessage* __that) { static NativeFunction f{ "FChatMessage.FChatMessage(const FChatMessage&)" }; NativeCall<void, FChatMessage *>(this, f, __that); }
	FChatMessage* operator=(FChatMessage* __that) { static NativeFunction f{ "FChatMessage.operator=" }; return NativeCall<FChatMessage *, FChatMessage *>(this, f, __that); }
};

